There exists a constant $c=-5\log(\alpha\beta)$ such that if both $T(i_0)$ and $T(i_1)$ are central and balanced, and $u_2(i_0)\geq c$ then
\begin{equation}
    g(i_0, i_1)\leq u_2(i_1)-u_2(i_0).
\end{equation}

Suppose $u_1(i-1) < u_1''$. If there is a crossing, then $v_1(i) - v_1(i-1) > 0$. Otherwise,
    \begin{equation*}
        v_1(i) - v_1(i-1) \geq \begin{cases}
            \log \beta, \quad \text{if the transmission is correct},\\
            \log \alpha, \quad \text{if the transmission is incorrect}.
        \end{cases}
    \end{equation*}

If there is a crossing and $u_1(i-1) \geq u_1''$, then $v_2(i) - v_2(i-1) \geq - \log \beta$. If there is no crossing, then
    \begin{equation*}
        v_2(i)-v_2(i-1) \geq \begin{cases}
            \log \beta, \quad \text{if the transmission is correct},\\
            \log \alpha, \quad \text{if the transmission is incorrect and } v_2(i-1) < \log \beta,\\
            -\log \beta \ (\geq \log \alpha), \quad \text{if the transmission is incorrect and } v_2(i-1) \geq \log \beta.
        \end{cases}
    \end{equation*}

If $T(i-1)$ is central and there is a crossing between moments $(i-1)$ and $i$, then $v(i)-v(i-1)\geq -\log\beta$. Otherwise, 
\begin{align*}
v(i)-v(i-1)&\geq
\begin{cases}
\log\beta,\quad &\text{if transmission is correct},\\
\log\alpha,\quad &\text{if transmission is incorrect}. 
\end{cases}
\end{align*}

Let the maximal fraction of substitution errors be $\tau \in [0,1/3)$. For any $\varepsilon >0$, there exists $\alpha\in[0,(3-\sqrt{5})/2]$ such that for $n$ sufficiently large, the encoding procedure over the adversarial substitution channel with feedback can correct up to $\tau n$ errors with transmission rate at least $R_s(\tau) - \varepsilon$, where
    \begin{equation*}
	R_{s}(\tau)=\begin{cases}
	1 - h(\tau),\quad &\text{ for }0\le\tau\le (3-\sqrt{5})/4, \\
	(1-3\tau)\log\left(\frac{1+\sqrt{5}}{2}\right),\quad &\text{ for }(3-\sqrt{5})/4< \tau\le 1/3.
	\end{cases}
	\end{equation*}
